//! The Follow Path real-machine gate (ADR 0109): follow-path.moho was generated by Moho
//! Pro 14.4 (Lua, CASES #10) — an empty "FollowLayer" follows Layer 1's S curve (Moho mesh
//! curve 17, three points at (-0.3, 0.3) → (0.0, -0.1) → (0.3, 0.3) inches, no shape of its
//! own), rotated along it, with the progress channel animated 1.0 → 0.0 over frames 0 → 50.
//! Moho places the follower at the curve percentage the channel names (the scripting API's
//! `startingCurvePercentage` and the Follow Path tool's percentage semantics); at 0 % the
//! follower sits exactly on the curve's first point — an expectation the file's own geometry
//! pins without needing Moho's handle formula.
//!
//! The gate gives the empty follower a square centred on its origin, renders through the
//! CPU oracle and checks where it landed: frame 50 (progress 0) puts its centre on the
//! curve start, frame 0 (progress 1 %) a step along the curve from there, and the display
//! item's rotation matches the first segment's tangent. The bend flag alone stays counted —
//! the vendor publishes no bend algorithm and the corpus holds no bent specimen.

use anicraft_mohoproj_import::import_path;
use std::sync::Arc;
use std::path::{Path, PathBuf};

fn corpus() -> Option<PathBuf> {
    if let Some(dir) = std::env::var_os("MAOHOU_FIXTURES") {
        let p = PathBuf::from(dir);
        if p.is_dir() {
            return Some(p);
        }
    }
    let beside = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../maop-corpus/maop");
    beside.is_dir().then_some(beside)
}

/// The stage pixel of a Moho point (inches, y up, centre origin; ADR 0101's MOHO_DPI).
fn to_px(w: u32, h: u32, x: f64, y: f64) -> (f32, f32) {
    ((w as f32 / 2.0 + (x * 320.0) as f32), (h as f32 / 2.0 - (y * 320.0) as f32))
}

#[test]
fn imported_follow_path_rides_the_curve() {
    let Some(dir) = corpus() else {
        eprintln!("skipped: no maop-corpus beside the workspace");
        return;
    };
    let path = dir.join("follow-path.moho");
    if !path.is_file() {
        eprintln!("skipped: no follow-path.moho in the corpus");
        return;
    }
    let (mut doc, report) = import_path(&path).unwrap_or_else(|e| panic!("follow-path.moho: {e}"));
    for gone in ["follow-path relations", "rotate to follow", "follow progress animation"] {
        assert!(!report.skipped.keys().any(|k| k.contains(gone)), "{gone} imports now: {:?}", report.skipped);
    }
    assert_eq!(report.skipped.get("follow bending (the artwork rides the path, it does not bend)"), Some(&1), "{:?}", report.skipped);
    let (w, h) = (doc.stage.width, doc.stage.height);
    assert_eq!((w, h), (1280, 720));
    let follow_target = doc.timeline(0).layers[0].follow.as_ref().expect("the FollowLayer carries the relation");
    let (follow_element, layer1_id) = (follow_target.element, follow_target.target);
    let (start_x, start_y) = to_px(w, h, -0.3, 0.3);

    // A square centred on the follower's origin, so rotation cannot move its centre.
    let mut rider = doc.timeline(0).layers[0].clone();
    {
        let rider = Arc::make_mut(&mut rider);
        let mut square = anicraft_geom::Path::default();
        square.move_to(anicraft_geom::Vec2::new(-10.0, -10.0)).line_to(anicraft_geom::Vec2::new(10.0, -10.0)).line_to(anicraft_geom::Vec2::new(10.0, 10.0)).line_to(anicraft_geom::Vec2::new(-10.0, 10.0)).close();
        let mut kf = (*rider.keyframes[0]).clone();
        kf.elements.push(std::sync::Arc::new(anicraft_doc::Element {
            id: anicraft_doc::ElementId(u64::MAX - 1),
            name: String::new(),
            transform: anicraft_geom::Affine::IDENTITY,
            color: Default::default(),
            kind: anicraft_doc::ElementKind::Shape(anicraft_doc::Shape {
                path: std::sync::Arc::new(square),
                fill: Some(anicraft_doc::Paint::Solid(anicraft_doc::Rgba::BLACK)),
                stroke: None,
                fill_rule: anicraft_geom::FillRule::NonZero,
                merge: false,
                bind: Vec::new(),
                points: Vec::new(),
                trim: None,
                texture: None,
            }),
        }));
        rider.keyframes = vec![std::sync::Arc::new(kf)];
    }
    // Hide the target's own artwork: its curve drives the follower regardless of
    // visibility, and the render then shows only the square.
    {
        let tl = doc.timeline_mut(0);
        let mut target = tl.layers[1].clone();
        Arc::make_mut(&mut target).visible = false;
        tl.layers[1] = target;
    }
    doc.timeline_mut(0).layers[0] = rider;

    // Where the square landed: its filled pixels' centroid, through the CPU oracle.
    let centre = |frame: u32| -> (f32, f32) {
        let dl = anicraft_doc::evaluate(&doc, frame);
        let view = anicraft_render::View { transform: anicraft_geom::Affine::IDENTITY, width: w, height: h, background: None };
        let pm = anicraft_render::render(&dl, &view).unwrap().0;
        let (mut sx, mut sy, mut n) = (0.0f64, 0.0f64, 0u64);
        for (i, p) in pm.data.iter().enumerate() {
            if p[3] > 0.5 {
                sx += (i as u64 % w as u64) as f64;
                sy += (i as u64 / w as u64) as f64;
                n += 1;
            }
        }
        assert!(n > 0, "the square draws at frame {frame}");
        ((sx / n as f64) as f32, (sy / n as f64) as f32)
    };

    // Frame 50: progress 0 — the centre sits exactly on the curve's first point.
    let (cx, cy) = centre(50);
    assert!((cx - start_x).abs() < 1.5 && (cy - start_y).abs() < 1.5, "frame 50: the follower centres on the curve start ({cx}, {cy}) vs ({start_x}, {start_y})");

    // Frame 0: progress 1 % — a small step along the curve from the start.
    let (x0, y0) = centre(0);
    let step = ((x0 - start_x).hypot(y0 - start_y)) as f64;
    assert!(step > 0.5, "progress 1 % moves off the start ({step} px)");
    assert!(step < 20.0, "progress 1 % is a small step ({step} px)");

    // Rotate to follow: the display item's matrix turns by the first segment's tangent
    // (points 34 → 35: Δ (0.3, -0.4) inches, y flipped into screen pixels).
    let dl = anicraft_doc::evaluate(&doc, 50);
    let item = dl.items.iter().find(|i| i.element == anicraft_doc::ElementId(u64::MAX - 1)).expect("the square's display item");
    let want = (128.0f64.atan2(96.0)) as f32;
    let angle = item.transform.m[1].atan2(item.transform.m[0]);
    assert!((angle - want).abs() < 0.02, "the follower turns to the tangent: {angle} vs {want}");
    // The followed curve itself stays invisible (no fill, no stroke — nothing to draw).
    assert!(!dl.items.iter().any(|i| i.layer == layer1_id && i.element == follow_element), "the followed curve draws nothing");
}
